insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-01', 'Équipe', 'Nouveau lead assigné', null, '{"subject": "Nouveau lead : Gestion Bélanger (12 portes)", "pre": "Assigné à vous, à tour de rôle · premier appel d’ici 1 h", "label": "Admin", "icon": "user", "eyebrow": "Ventes", "title": "Gestion Bélanger vous est assigné", "blocks": [["kv", {"rows": [["Source", "Formulaire du site"], ["Immeuble", "12 portes · Saint-Roch"], ["Valeur estimée", "855 $ par mois"], ["Objectif", "Premier appel d’ici 1 h"]]}], ["quote", {"t": "Bonjour, nous cherchons un gestionnaire pour notre immeuble de 12 logements à Saint-Roch…", "by": "Message du formulaire"}]], "cta": {"l": "Ouvrir le deal"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare ; une personne décide."}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Lead routé", "send": "Automatique", "when": "Immédiat aux heures de bureau, sinon le lendemain à 8 h", "lcap": "Interne"}}'::jsonb, 'Nouveau lead : Gestion Bélanger (12 portes)', 'Assigné à vous, à tour de rôle · premier appel d’ici 1 h', array['responsable', 'lead', 'source', 'valeur', 'message']::text[], 'Lead routé', 'auto', false, 'internal', false, false)
