insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-04', 'Équipe', 'Échec d’une automatisation', null, '{"subject": "Échec : classement d’un document (Bail Côté.pdf)", "pre": "Fichier protégé par un mot de passe · rien n’a été supprimé", "label": "Admin", "icon": "alert", "eyebrow": "Automatisation", "title": "Cléo n’a pas pu classer un document", "intro": "Le fichier « Bail Côté.pdf », reçu du portail locataire à 10 h 02, est protégé par un mot de passe.", "blocks": [["notice", {"k": "info", "title": "Ce qui a été fait", "t": "Rien n’a été classé ni supprimé. Le fichier attend dans « Échecs à traiter »."}]], "cta": {"l": "Demander une version lisible", "link": "Classer à la main"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare ; une personne décide."}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Exécution en échec", "send": "Automatique (regroupé si plusieurs)", "when": "Heures de bureau", "lcap": "Interne"}}'::jsonb, 'Échec : classement d’un document (Bail Côté.pdf)', 'Fichier protégé par un mot de passe · rien n’a été supprimé', array['automatisation', 'cause', 'fichier']::text[], 'Exécution en échec', 'auto', false, 'internal', false, false)
