insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-05', 'Équipe', 'Invitation à l’équipe', null, '{"subject": "Steven Paradis vous invite dans l’admin de Lease Lane", "pre": "Rôle : Comptabilité · accès externe", "label": "Invitation", "icon": "users", "eyebrow": "Invitation", "title": "Bienvenue dans l’équipe, Marc", "blocks": [["kv", {"rows": [["Rôle", "Comptabilité (externe)"], ["Accès", "Finances et rapports"], ["Invitation valable", "72 heures"]]}], ["notice", {"k": "info", "ic": "lock", "title": "Double authentification", "t": "Elle est obligatoire pour tous. Gardez votre téléphone à portée de main pour l’étape suivante."}]], "cta": {"l": "Accepter l’invitation"}, "sign": {"ini": "SP", "name": "Steven Paradis", "role": "Administrateur · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Steven Paradis vous a invité dans l’admin de Lease Lane."}, "spec": {"trigger": "Invitation créée (Équipe et permissions)", "send": "Automatique", "when": "Immédiat", "lcap": "Transactionnel"}}'::jsonb, 'Steven Paradis vous invite dans l’admin de Lease Lane', 'Rôle : Comptabilité · accès externe', array['prenom', 'role', 'acces', 'lien_invitation']::text[], 'Invitation créée (Équipe et permissions)', 'auto', false, 'transactional', false, false)
