insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-06', 'Équipe', 'Code de connexion', null, '{"subject": "Votre code de connexion : 482 913", "pre": "Valable 10 minutes. Ne le donnez à personne.", "label": "Sécurité", "icon": "lock", "eyebrow": "Sécurité", "title": "Votre code de connexion", "blocks": [["code", {"v": "482913"}], ["notice", {"k": "info", "title": "Ce n’est pas vous?", "t": "Ne donnez ce code à personne, même à Lease Lane. Si vous n’avez pas tenté de vous connecter, changez votre mot de passe."}]], "foot": {"reason": "Courriel de sécurité envoyé à chaque connexion depuis un nouvel appareil."}, "spec": {"trigger": "Connexion depuis un nouvel appareil", "send": "Automatique", "when": "Immédiat", "lcap": "Transactionnel (sécurité)", "note": "Le code expire après 10 minutes ou un seul usage."}}'::jsonb, 'Votre code de connexion : 482 913', 'Valable 10 minutes. Ne le donnez à personne.', array['code', 'appareil', 'heure']::text[], 'Connexion depuis un nouvel appareil', 'auto', true, 'transactional', false, false)
