insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-07', 'Équipe', 'Rapport hebdomadaire', null, '{"subject": "Semaine du 5 octobre : 1 mandat signé, 34 leads ce mois", "pre": "La conversion monte à 38 % · les propositions dépassent la cible", "label": "Rapport d’équipe", "icon": "chart", "eyebrow": "Rapport d’équipe", "title": "Votre semaine en un coup d’œil", "blocks": [["kv", {"rows": [["Leads", "34 · +6"], ["Mandats signés", "1 cette semaine"], ["Conversion", "38 %"], ["Cycle moyen", "19 jours"]]}], ["bars", {"v": [2, 1, 2, 2, 2, 2], "lab": ["mai", "juin", "juil.", "août", "sept.", "oct."], "top": "2 mandats"}], ["notice", {"k": "info", "title": "À surveiller", "t": "Les propositions prennent 8,2 jours (cible : 7). Relancez Immeubles Fortier et Société Lacasse."}]], "cta": {"l": "Ouvrir le tableau de bord"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare ; une personne décide."}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Chaque lundi", "send": "Automatique", "when": "7 h 30", "lcap": "Interne"}}'::jsonb, 'Semaine du 5 octobre : 1 mandat signé, 34 leads ce mois', 'La conversion monte à 38 % · les propositions dépassent la cible', array['semaine', 'indicateurs', 'a_surveiller']::text[], 'Chaque lundi', 'auto', false, 'internal', false, false)
