insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-08', 'Équipe', 'Panne détectée', 'Lease Lane · Panne : {service} ne répond plus normalement depuis {debut}. Détails dans l’admin, onglet Supervision.', '{"subject": "Panne : SMS retardés depuis 11 h 52", "pre": "3 emplacements sur 3 le confirment · le repli par courriel est actif", "label": "Supervision", "icon": "siren", "eyebrow": "Incident INC-2026-014", "title": "L’envoi de SMS est retardé", "intro": "Depuis 11 h 52, le fournisseur SMS répond en 9 secondes au lieu de 2. Les 3 emplacements de vérification le confirment.", "accent": "urgent", "blocks": [["kv", {"rows": [["Début", "Aujourd’hui, 11 h 52"], ["Service touché", "SMS (fournisseur externe)"], ["En attente", "14 SMS · aucun perdu"]]}], ["steps", {"rows": [[1, "Détection", "11 h 52 · 3 emplacements sur 3"], [1, "Repli automatique", "11 h 54 · rappels urgents et codes de connexion par courriel"], [2, "Suivi du fournisseur", "nouvelle vérification toutes les 5 minutes"], [0, "Retour à la normale", "vous recevrez un courriel de confirmation"]]}]], "cta": {"l": "Ouvrir l’incident"}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Une interface ou un service ne répond plus normalement (3 emplacements sur 3)", "send": "Automatique", "when": "Immédiat, jour et nuit", "lcap": "Interne", "note": "Quand le SMS est en cause, l’alerte part seulement par courriel et dans l’admin."}}'::jsonb, 'Panne : SMS retardés depuis 11 h 52', '3 emplacements sur 3 le confirment · le repli par courriel est actif', array['service', 'debut', 'impact', 'repli', 'lien_incident']::text[], 'Une interface ou un service ne répond plus normalement (3 emplacements sur 3)', 'auto', true, 'internal', false, false)
