insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-09', 'Équipe', 'Service rétabli', null, '{"subject": "Rétabli : les SMS partent de nouveau", "pre": "Incident de 32 minutes · 14 SMS envoyés · aucun perdu", "label": "Supervision", "icon": "check", "eyebrow": "Incident INC-2026-014 · fermé", "title": "Les SMS partent de nouveau normalement", "intro": "Depuis 12 h 24, le fournisseur répond de nouveau en moins de 2 secondes. L’incident a duré 32 minutes.", "blocks": [["kv", {"rows": [["Durée", "32 minutes"], ["SMS en attente", "14 envoyés à 12 h 25"], ["Perdus", "Aucun"], ["Cause", "Panne sur le réseau du fournisseur"]]}], ["notice", {"k": "info", "ic": "history", "title": "Encore en pause", "t": "La séquence « Rappels de visite (SMS) » attend toujours. Reprenez-la dans Automatisations : rien ne repart sans une personne."}]], "cta": {"l": "Voir le rapport d’incident"}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Service stable depuis 15 minutes", "send": "Automatique", "when": "Au retour à la normale", "lcap": "Interne", "note": "L’incident est fermé seulement après 15 minutes stables sur les 3 emplacements."}}'::jsonb, 'Rétabli : les SMS partent de nouveau', 'Incident de 32 minutes · 14 SMS envoyés · aucun perdu', array['service', 'duree', 'envoyes', 'cause', 'en_pause', 'lien_incident']::text[], 'Service stable depuis 15 minutes', 'auto', false, 'internal', false, false)
