insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-10', 'Équipe', 'Rapport de supervision', null, '{"subject": "Supervision, semaine du 5 octobre : 99,97 % en ligne", "pre": "Aucun incident · 3 liens brisés à corriger · coût IA à surveiller", "label": "Supervision", "icon": "gauge", "eyebrow": "Rapport de supervision", "title": "Votre plateforme cette semaine", "blocks": [["kv", {"rows": [["Disponibilité", "99,97 %"], ["Incidents", "Aucun (le dernier date du 4 oct.)"], ["Parcours critiques", "6 sur 6 réussis à 99,8 %"], ["Coût IA", "108,70 $"]]}], ["table", {"head": ["À corriger sur le site", "Nombre"], "rows": [["Liens brisés", "3"], ["Fautes en français", "2"], ["Fautes en anglais", "1"], ["Pages sans description", "2"]]}], ["notice", {"k": "info", "title": "À surveiller", "t": "Au rythme actuel, le coût IA dépassera le budget vers le 27 octobre. Le modèle léger pour l’analyse des courriels le ramènerait à 396 $."}]], "cta": {"l": "Ouvrir la supervision"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare ; une personne décide."}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Chaque lundi", "send": "Automatique", "when": "7 h", "lcap": "Interne", "note": "Peut aussi partir à une personne sans accès à l’admin (comptable, partenaire), sur invitation."}}'::jsonb, 'Supervision, semaine du 5 octobre : 99,97 % en ligne', 'Aucun incident · 3 liens brisés à corriger · coût IA à surveiller', array['semaine', 'disponibilite', 'incidents', 'a_corriger', 'cout_ia', 'a_surveiller']::text[], 'Chaque lundi', 'auto', false, 'internal', false, false)
