insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-11', 'Équipe', 'Envois suspendus', null, '{"subject": "Tous les envois automatiques sont suspendus", "pre": "Par {par} à {heure} · {raison}", "label": "Automatisations", "icon": "zap", "eyebrow": "Coupe-circuit", "title": "Les envois automatiques sont en pause", "intro": "{par} a suspendu les envois automatiques à {heure}. Rien ne part tant qu’une personne ne les réactive pas.", "accent": "urgent", "blocks": [["kv", {"rows": [["Raison", "{raison}"], ["Durée", "{duree}"], ["Envois retenus", "{envois_retenus}"]]}], ["bullets", {"items": ["Cléo répond toujours aux messages reçus, sans rien envoyer d’elle-même.", "Les avis déjà approuvés attendent aussi la reprise.", "La reprise sera inscrite au journal, avec son auteur et sa raison."]}]], "cta": {"l": "Voir les automatisations", "href": "{lien}"}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Coupe-circuit activé (Cléo et IA › Automatisations)", "send": "Automatique", "when": "Immédiat", "lcap": "Interne", "note": "Un second courriel part à la reprise des envois."}, "exemple": {"par": "Steven Paradis", "heure": "12 h 10", "raison": "Erreur de montant dans LOC-05", "duree": "Jusqu’à la réactivation", "envois_retenus": "23", "lien": "https://app.leaselane.ca/"}}'::jsonb, 'Tous les envois automatiques sont suspendus', 'Par {par} à {heure} · {raison}', array['duree', 'envois_retenus', 'heure', 'lien', 'par', 'raison']::text[], 'Coupe-circuit activé (Cléo et IA › Automatisations)', 'auto', true, 'internal', false, true)
