insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-12', 'Équipe', 'Budget IA à 80 %', null, '{"subject": "Budget IA de septembre : 80 % utilisé", "pre": "320 $ sur 400 $ le 22 · projection de 455 $ si rien ne change", "label": "Routeur IA", "icon": "dollar", "eyebrow": "Coûts IA", "title": "Le budget IA de septembre est utilisé à 80 %", "blocks": [["meter", {"label": "Budget de septembre", "value": "320 $ sur 400 $", "r": 0.8, "cap": "Projection : 455 $ à la fin du mois si rien ne change."}], ["table", {"head": ["Agent", "Coût du mois"], "rows": [["Cléo (conversations)", "158,40 $"], ["Analyse des courriels", "71,10 $"], ["Prospection IA", "47,80 $"], ["Rédaction juridique", "26,30 $"], ["Rapprochement bancaire", "16,40 $"]], "total": ["Total", "320,00 $"]}], ["notice", {"k": "info", "ic": "spark", "title": "Une piste", "t": "Le modèle léger garde 97 % de précision pour l’analyse des courriels et coûterait 66 $ de moins par mois."}]], "cta": {"l": "Ouvrir le routeur IA"}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Coût IA du mois à 80 % du budget", "send": "Automatique", "when": "Une fois par seuil : 80 %, puis 100 %", "lcap": "Interne", "note": "Aucun appel n’est coupé automatiquement : une personne décide. Seules les métadonnées sont gardées, jamais le contenu des conversations."}}'::jsonb, 'Budget IA de septembre : 80 % utilisé', '320 $ sur 400 $ le 22 · projection de 455 $ si rien ne change', array['mois', 'depense', 'budget', 'projection', 'piste']::text[], 'Coût IA du mois à 80 % du budget', 'auto', false, 'internal', false, false)
