insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-13', 'Équipe', 'Écart visuel', null, '{"subject": "Version 2.14 : 1 écart visuel à vérifier", "pre": "Payer le loyer · Safari sur iPhone · 4,2 % des pixels", "label": "Supervision", "icon": "image", "eyebrow": "Comparaison visuelle", "title": "Un écran a changé après la mise à jour", "intro": "Après la version 2.14 de l’Espace locataire, 95 captures sur 96 sont identiques à la référence. Une seule diffère.", "blocks": [["kv", {"rows": [["Page", "Payer le loyer"], ["Navigateur", "Safari sur iPhone"], ["Écart", "4,2 % des pixels"], ["Cause probable", "Nouvelle barre de navigation"]]}], ["notice", {"k": "info", "ic": "sliders", "title": "Retrait sans redéploiement", "t": "Désactivez l’interrupteur « Nouvelle barre de navigation (2.14) » : la page revient à la version précédente pour les 10 % de locataires concernés."}]], "cta": {"l": "Comparer les captures"}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Écart visuel détecté après une mise à jour", "send": "Automatique", "when": "Après chaque déploiement", "lcap": "Interne", "note": "Les captures utilisent des comptes témoins : aucune donnée réelle n’y figure."}}'::jsonb, 'Version 2.14 : 1 écart visuel à vérifier', 'Payer le loyer · Safari sur iPhone · 4,2 % des pixels', array['version', 'page', 'navigateur', 'ecart', 'interrupteur', 'lien_comparaison']::text[], 'Écart visuel détecté après une mise à jour', 'auto', false, 'internal', false, false)
