insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('EQP-14', 'Équipe', 'Amélioration en ligne', null, '{"subject": "En ligne : les photos dans les demandes d’entretien", "pre": "Demandée par 22 locataires · livrée le 2 octobre", "label": "Améliorations", "icon": "rocket", "eyebrow": "Amélioration livrée", "title": "Les photos arrivent dans les demandes d’entretien", "intro": "Julie, l’amélioration que vous avez portée est en ligne : un locataire peut joindre jusqu’à 5 photos à une demande d’entretien.", "blocks": [["steps", {"rows": [[1, "Demandée", "22 locataires, par Cléo, depuis juin"], [1, "Cadrée", "12 août · portée validée"], [1, "Développée", "septembre"], [1, "En ligne", "2 octobre"]]}], ["kv", {"rows": [["Inclus", "Jusqu’à 5 photos par demande"], ["Reporté", "Vidéos (à revoir en 2027)"]]}], ["p", {"t": "Cléo propose d’en informer les 22 locataires. Vous décidez dans Opérations, onglet À approuver."}]], "cta": {"l": "Voir l’amélioration"}, "foot": {"reason": "Courriel interne de l’admin Lease Lane. Réglez vos alertes dans Rapports et réglages."}, "spec": {"trigger": "Amélioration livrée (Rapports et réglages › Améliorations)", "send": "Automatique", "when": "À la mise en ligne", "lcap": "Interne"}}'::jsonb, 'En ligne : les photos dans les demandes d’entretien', 'Demandée par 22 locataires · livrée le 2 octobre', array['prenom', 'amelioration', 'date', 'inclus', 'reporte']::text[], 'Amélioration livrée (Rapports et réglages › Améliorations)', 'auto', false, 'internal', false, false)
