insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('FOU-01', 'Fournisseurs', 'Demande de soumission', null, '{"subject": "Demande de soumission : chauffe-eau au 640, 3e Avenue — 3", "pre": "Réponse souhaitée d’ici le 11 octobre, 17 h", "label": "Soumission", "icon": "wrench", "eyebrow": "Demande de soumission", "title": "Pouvez-vous nous soumettre un prix?", "blocks": [["kv", {"rows": [["Travaux", "Remplacer un chauffe-eau de 40 gallons"], ["Adresse", "640, 3e Avenue — 3, Limoilou"], ["Accès", "Avec la locataire, sur rendez-vous"], ["Réponse souhaitée", "11 octobre, 17 h"]]}], ["bullets", {"items": ["Prix taxes en sus, pièces et main-d’œuvre détaillées", "Votre première disponibilité", "La garantie offerte"]}]], "cta": {"l": "Envoyer ma soumission"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que votre entreprise fait partie des fournisseurs de Lease Lane."}, "spec": {"trigger": "Bon de travail en mode soumission", "send": "Automatique", "when": "Jour ouvrable, entre 8 h et 17 h", "lcap": "Transactionnel (relation d’affaires)"}}'::jsonb, 'Demande de soumission : chauffe-eau au 640, 3e Avenue — 3', 'Réponse souhaitée d’ici le 11 octobre, 17 h', array['fournisseur', 'travaux', 'adresse', 'acces', 'date_limite']::text[], 'Bon de travail en mode soumission', 'auto', false, 'transactional', false, false)
