insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('FOU-03', 'Fournisseurs', 'Relance de soumission', null, '{"subject": "Rappel : votre soumission pour BT-2026-126", "pre": "Nous attendons votre prix d’ici demain midi.", "label": "Soumission", "icon": "clock", "eyebrow": "Rappel", "title": "Votre soumission nous aiderait", "intro": "Bonjour, nous n’avons pas encore reçu votre prix pour la réfection de toiture au 1180, Cartier. Êtes-vous toujours intéressés?", "blocks": [["kv", {"rows": [["Référence", "BT-2026-126"], ["Réponse souhaitée", "demain, midi"]]}]], "cta": {"l": "Envoyer ma soumission", "link": "Pas disponible cette fois"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que votre entreprise fait partie des fournisseurs de Lease Lane."}, "spec": {"trigger": "Soumission sans réponse après 48 h", "send": "Automatique · une seule relance", "when": "Jour ouvrable, 9 h", "lcap": "Transactionnel (relation d’affaires)"}}'::jsonb, 'Rappel : votre soumission pour BT-2026-126', 'Nous attendons votre prix d’ici demain midi.', array['fournisseur', 'numero_bt', 'travaux', 'date_limite']::text[], 'Soumission sans réponse après 48 h', 'auto', false, 'transactional', false, false)
