insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('FOU-05', 'Fournisseurs (recrutement)', 'Invitation, banque de fournisseurs', null, '{"subject": "Rejoignez la banque de fournisseurs de Lease Lane", "pre": "Déneigement à Lévis · 3 documents à fournir", "label": "Recrutement", "icon": "users", "eyebrow": "Recrutement", "title": "Travaillons ensemble à Lévis", "intro": "Nous gérons 42 logements à Lévis et cherchons une entreprise de déneigement fiable pour l’hiver 2026-2027.", "blocks": [["bullets", {"items": ["Licence RBQ, s’il y a lieu", "Preuve d’assurance responsabilité", "Vos prix pour la saison"]}]], "cta": {"l": "Créer mon profil fournisseur"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que votre entreprise affiche publiquement ses services de déneigement à Lévis.", "commercial": true}, "spec": {"trigger": "Fournisseur trouvé par l’agent, puis vérifié", "send": "Après approbation humaine", "when": "Jour ouvrable, entre 9 h et 17 h", "lcap": "Commercial · désabonnement obligatoire", "note": "Une invitation, une relance au plus."}}'::jsonb, 'Rejoignez la banque de fournisseurs de Lease Lane', 'Déneigement à Lévis · 3 documents à fournir', array['entreprise', 'service', 'territoire', 'documents']::text[], 'Fournisseur trouvé par l’agent, puis vérifié', 'after_approval', false, 'commercial', true, false)
