insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-01', 'Locataires', 'Invitation au portail locataire', 'Lease Lane : votre portail locataire est prêt. Activez votre accès : leaselane.ca/a/8F2K', '{"subject": "Votre accès au portail locataire Lease Lane", "pre": "Payez votre loyer, faites une demande et signez vos documents au même endroit.", "label": "Portail locataire", "icon": "key", "eyebrow": "Bienvenue", "title": "William, votre portail locataire est prêt", "intro": "Votre bail au 420, Saint-Joseph E. — 5 commence le 1er décembre. Le portail réunit tout ce dont vous aurez besoin.", "blocks": [["bullets", {"items": ["Payer votre loyer et retrouver vos reçus", "Faire une demande d’entretien, photo à l’appui", "Signer vos documents et relire votre bail", "Écrire à Cléo, jour et nuit"]}], ["notice", {"k": "info", "ic": "lock", "title": "Un lien personnel", "t": "Il est valable 7 jours. Vous choisirez ensuite votre mot de passe et la double authentification."}]], "cta": {"l": "Activer mon accès", "link": "Une question? Répondez simplement à ce courriel."}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous signez un bail géré par Lease Lane."}, "spec": {"trigger": "Bail signé (processus Emménagement)", "send": "Automatique", "when": "Immédiat, entre 8 h et 22 h", "lcap": "Transactionnel · désabonnement non requis", "note": "Lien unique : il expire après 7 jours ou à la première utilisation."}}'::jsonb, 'Votre accès au portail locataire Lease Lane', 'Payez votre loyer, faites une demande et signez vos documents au même endroit.', array['prenom', 'adresse_logement', 'date_debut_bail', 'lien_activation', 'gestionnaire']::text[], 'Bail signé (processus Emménagement)', 'auto', false, 'transactional', false, false)
