insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-02', 'Locataires', 'Demande bien reçue', 'Lease Lane : demande DEM-2026-0161 reçue (prioritaire). Un technicien vous écrira avant de passer.', '{"subject": "Demande DEM-2026-0161 reçue : fuite sous l’évier", "pre": "Un technicien vous écrira avant de passer.", "label": "Demande d’entretien", "icon": "inbox", "eyebrow": "Demande d’entretien", "title": "Nous avons bien reçu votre demande", "intro": "Merci, Martin. Cléo l’a classée « prioritaire » : la fuite est contenue, mais elle doit être réparée dans les 48 heures.", "blocks": [["kv", {"rows": [["Numéro", "DEM-2026-0161"], ["Logement", "1180, Cartier — 3"], ["Problème", "Fuite sous l’évier"], ["Priorité", "Prioritaire · sous 48 h"]]}], ["steps", {"rows": [[1, "Demande reçue", "aujourd’hui, 8 h 14"], [2, "Technicien assigné", "vous recevrez son nom et l’heure de passage"], [0, "Intervention", ""], [0, "Demande fermée", "après votre confirmation"]]}], ["notice", {"k": "info", "title": "En attendant", "t": "Fermez la valve sous l’évier et placez un seau. Si l’eau coule encore, écrivez « urgence » à Cléo : elle joint le technicien de garde."}]], "cta": {"l": "Suivre ma demande"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare les messages ; une personne vérifie ce qui compte."}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Demande créée (portail, SMS ou courriel)", "send": "Automatique", "when": "Immédiat, à toute heure (service essentiel)", "lcap": "Transactionnel"}}'::jsonb, 'Demande DEM-2026-0161 reçue : fuite sous l’évier', 'Un technicien vous écrira avant de passer.', array['prenom', 'numero_demande', 'adresse_logement', 'probleme', 'priorite']::text[], 'Demande créée (portail, SMS ou courriel)', 'auto', true, 'transactional', false, false)
