insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-03', 'Locataires', 'Avis d’entrée du technicien', 'Lease Lane : Plomberie Capitale passera jeudi 15 oct. entre 8 h et 10 h (DEM-2026-0161). Répondez 1 pour confirmer.', '{"subject": "Plomberie Capitale passera jeudi entre 8 h et 10 h", "pre": "Avis d’entrée dans votre logement · DEM-2026-0161", "label": "Avis d’entrée", "icon": "calendar", "eyebrow": "Avis d’entrée", "title": "Un plombier passera jeudi matin", "intro": "Nous vous avisons au moins 24 heures à l’avance, comme le prévoit la loi. Vous n’avez pas besoin d’être présent.", "blocks": [["event", {"mon": "OCT.", "day": "15", "time": "Jeudi 15 octobre · entre 8 h et 10 h", "place": "1180, Cartier — 3 · Plomberie Capitale"}], ["notice", {"k": "legal", "title": "Votre droit", "t": "Sauf urgence, le locateur donne un préavis de 24 heures avant d’entrer pour des travaux (art. 1931 C.c.Q.). Vous pouvez proposer une autre plage."}]], "cta": {"l": "Confirmer la plage", "link": "Proposer une autre plage"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Bon de travail planifié", "send": "Automatique", "when": "Au moins 24 h avant la visite, entre 8 h et 22 h", "lcap": "Transactionnel (avis légal)"}}'::jsonb, 'Plomberie Capitale passera jeudi entre 8 h et 10 h', 'Avis d’entrée dans votre logement · DEM-2026-0161', array['prenom', 'fournisseur', 'date_visite', 'plage_horaire', 'adresse_logement']::text[], 'Bon de travail planifié', 'auto', false, 'legal', false, false)
