insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-04', 'Locataires', 'Demande terminée', null, '{"subject": "C’est réparé : {probleme} ({numero_demande})", "pre": "Dites-nous si tout est correct, en un clic.", "label": "Demande d’entretien", "icon": "check", "eyebrow": "Demande fermée", "title": "C’est réparé : {probleme}", "intro": "{fournisseur} a terminé l’intervention le {date_intervention}.", "blocks": [["kv", {"rows": [["Intervention", "{travaux}"], ["Durée", "{duree}"], ["Coût pour vous", "{cout_locataire}"]]}], ["p", {"t": "Tout fonctionne bien? Votre avis nous aide à choisir les bons fournisseurs."}]], "cta": {"l": "Tout est correct", "href": "{lien_confirmation}", "link": "Signaler un problème", "linkHref": "{lien_probleme}"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare les messages ; une personne vérifie ce qui compte."}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Bon de travail terminé et vérifié", "send": "Automatique", "when": "Le jour même, entre 8 h et 22 h", "lcap": "Transactionnel"}, "exemple": {"probleme": "Fuite sous l’évier", "numero_demande": "DEM-2026-0161", "fournisseur": "Plomberie Capitale", "date_intervention": "jeudi 15 octobre à 9 h 40", "travaux": "Remplacement du siphon", "duree": "35 minutes", "cout_locataire": "Aucun", "lien_confirmation": "https://app.leaselane.ca/?p=locataire", "lien_probleme": "https://app.leaselane.ca/?p=locataire"}}'::jsonb, 'C’est réparé : {probleme} ({numero_demande})', 'Dites-nous si tout est correct, en un clic.', array['cout_locataire', 'date_intervention', 'duree', 'fournisseur', 'lien_confirmation', 'lien_probleme', 'numero_demande', 'probleme', 'travaux']::text[], 'Bon de travail terminé et vérifié', 'auto', false, 'transactional', false, true)
