insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-05', 'Locataires', 'Rappel de loyer (J+1)', 'Lease Lane : votre loyer de {montant} ({mois}) n’est pas encore reçu. Payer : {lien_paiement}. Déjà payé? Ignorez ce message.', '{"subject": "Rappel : loyer {de_mois}", "pre": "Votre paiement de {montant} n’est pas encore arrivé.", "label": "Paiements", "icon": "wallet", "eyebrow": "Rappel", "title": "Votre loyer {de_mois} n’est pas encore arrivé", "intro": "{prenom}, c’est peut-être un oubli : le paiement de {montant} prévu le {echeance} n’apparaît pas encore à votre dossier.", "blocks": [["kv", {"rows": [["Montant", "{montant}"], ["Échéance", "{echeance}"], ["Logement", "{adresse_logement}"]]}], ["p", {"t": "Déjà payé? Ignorez ce message : un virement prend parfois un jour ouvrable."}]], "cta": {"l": "Payer maintenant", "href": "{lien_paiement}", "link": "Besoin d’une entente de paiement? Répondez à ce courriel."}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Loyer impayé à J+1", "send": "Automatique", "when": "J+1 à 9 h", "lcap": "Transactionnel"}, "exemple": {"prenom": "Gabriel", "montant": "1 195 $", "mois": "octobre", "de_mois": "d’octobre", "echeance": "1er octobre 2026", "adresse_logement": "640, 3e Avenue — 7", "lien_paiement": "https://app.leaselane.ca/?p=locataire", "gestionnaire": "Julie N.", "initiales_gestionnaire": "JN"}}'::jsonb, 'Rappel : loyer {de_mois}', 'Votre paiement de {montant} n’est pas encore arrivé.', array['adresse_logement', 'de_mois', 'echeance', 'gestionnaire', 'initiales_gestionnaire', 'lien_paiement', 'mois', 'montant', 'prenom']::text[], 'Loyer impayé à J+1', 'auto', false, 'transactional', false, true)
