insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-06', 'Locataires', 'Relance de loyer (J+7)', null, '{"subject": "Loyer {de_mois} : {jours_retard} jours de retard", "pre": "Parlons-en avant que le dossier passe au recouvrement.", "label": "Paiements", "icon": "alert", "eyebrow": "Relance", "title": "Votre loyer {de_mois} a {jours_retard} jours de retard", "intro": "{prenom}, nous n’avons pas reçu le loyer de {montant} dû le {echeance}. Si une difficulté vous empêche de payer, une entente reste possible.", "blocks": [["meter", {"label": "Retard", "value": "{jours_retard} jours", "r": "{ratio_retard}", "cap": "Au-delà de 3 semaines, le propriétaire peut demander la résiliation du bail (art. 1971 C.c.Q.)."}], ["kv", {"rows": [["Montant dû", "{montant}"], ["Logement", "{adresse_logement}"]]}]], "cta": {"l": "Payer {montant}", "href": "{lien_paiement}", "link": "Proposer une entente de paiement", "linkHref": "{lien_entente}"}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Loyer impayé à J+7", "send": "Automatique", "when": "J+7 à 9 h", "lcap": "Transactionnel", "note": "Ton ferme et respectueux, aucune menace. La mise en demeure (LOC-07) n’est jamais automatique : une personne l’approuve."}, "exemple": {"prenom": "Gabriel", "montant": "1 195 $", "de_mois": "d’octobre", "jours_retard": "7", "ratio_retard": "0.333", "echeance": "1er octobre 2026", "adresse_logement": "640, 3e Avenue — 7", "lien_paiement": "https://app.leaselane.ca/?p=locataire", "lien_entente": "mailto:info@leaselane.ca?subject=Entente%20de%20paiement", "gestionnaire": "Julie N.", "initiales_gestionnaire": "JN"}}'::jsonb, 'Loyer {de_mois} : {jours_retard} jours de retard', 'Parlons-en avant que le dossier passe au recouvrement.', array['adresse_logement', 'de_mois', 'echeance', 'gestionnaire', 'initiales_gestionnaire', 'jours_retard', 'lien_entente', 'lien_paiement', 'montant', 'prenom', 'ratio_retard']::text[], 'Loyer impayé à J+7', 'auto', false, 'transactional', false, true)
