insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-07', 'Locataires', 'Mise en demeure', null, '{"subject": "Mise en demeure : loyer d’octobre impayé", "pre": "Document officiel joint · paiement attendu dans les 10 jours", "label": "Avis officiel", "icon": "scale", "eyebrow": "Avis officiel", "title": "Mise en demeure : loyer d’octobre impayé", "intro": "Monsieur Paquet, vous trouverez ci-joint une mise en demeure concernant le loyer d’octobre 2026 (1 195 $), toujours impayé.", "blocks": [["doc", {"name": "Mise en demeure · JUR-2026-009", "meta": "Signée par Steven Paradis · 2 pages"}], ["kv", {"rows": [["Somme due", "1 195 $"], ["Délai pour payer", "10 jours après la réception"], ["Paiement", "Portail, Interac ou chèque"]]}], ["notice", {"k": "legal", "title": "Vos recours", "t": "Vous pouvez proposer une entente ou contester en répondant à ce courriel. Pour connaître vos droits : Tribunal administratif du logement, tal.gouv.qc.ca."}]], "cta": {"l": "Payer 1 195 $", "link": "Répondre à Lease Lane"}, "sign": {"ini": "SP", "name": "Steven Paradis", "role": "Pour Lease Lane, mandataire du locateur"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Mise en demeure approuvée (dossier de recouvrement)", "send": "Après approbation humaine, jamais automatique", "when": "Jour ouvrable, entre 9 h et 17 h", "lcap": "Transactionnel (avis légal)", "note": "Rédigée par Cléo à partir du modèle « Loyer impayé », relue et signée par une personne. La preuve d’envoi est conservée au dossier.", "files": "Mise en demeure signée (PDF, eZsign)"}}'::jsonb, 'Mise en demeure : loyer d’octobre impayé', 'Document officiel joint · paiement attendu dans les 10 jours', array['nom', 'montant', 'mois', 'numero_dossier', 'signataire']::text[], 'Mise en demeure approuvée (dossier de recouvrement)', 'after_approval', false, 'legal', false, false)
