insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-08', 'Locataires', 'Prélèvement refusé', null, '{"subject": "Votre prélèvement du 1er octobre a été refusé", "pre": "Nouvelle tentative le 15 octobre. Rien à faire si votre compte est approvisionné.", "label": "Paiements", "icon": "card", "eyebrow": "Paiement", "title": "Le prélèvement de votre loyer a été refusé", "intro": "Votre institution a refusé le prélèvement de 1 290 $ (fonds insuffisants). Ça arrive : nous réessaierons automatiquement le 15 octobre.", "blocks": [["kv", {"rows": [["Montant", "1 290 $"], ["Motif de la banque", "Fonds insuffisants"], ["Nouvelle tentative", "15 octobre 2026"]]}], ["p", {"t": "Vous préférez payer avant? Un virement Interac ou un paiement dans le portail annule la nouvelle tentative."}]], "cta": {"l": "Payer maintenant", "link": "Changer de compte bancaire"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare les messages ; une personne vérifie ce qui compte."}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Retour de prélèvement (Optimal Paiement)", "send": "Automatique", "when": "Le jour du retour, entre 8 h et 22 h", "lcap": "Transactionnel", "note": "Aucun ton accusateur ; ne jamais citer de frais bancaires qu’on ne connaît pas."}}'::jsonb, 'Votre prélèvement du 1er octobre a été refusé', 'Nouvelle tentative le 15 octobre. Rien à faire si votre compte est approvisionné.', array['prenom', 'montant', 'motif_banque', 'date_reprise', 'lien_paiement']::text[], 'Retour de prélèvement (Optimal Paiement)', 'auto', false, 'transactional', false, false)
