insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-09', 'Locataires', 'Reçu de paiement', null, '{"subject": "Reçu : loyer d’octobre payé", "pre": "Merci! 1 385 $ reçus le 1er octobre.", "label": "Paiements", "icon": "receipt", "eyebrow": "Reçu", "title": "Merci, votre loyer d’octobre est payé", "blocks": [["table", {"head": ["Description", "Montant"], "rows": [["Loyer d’octobre 2026", "1 325 $"], ["Stationnement", "60 $"]], "total": ["Total payé", "1 385 $"]}], ["kv", {"rows": [["Payé le", "1er octobre 2026"], ["Mode", "Prélèvement (PAD)"], ["Numéro de reçu", "R-2026-10-0412"]]}]], "cta": {"l": "Voir mes reçus"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare les messages ; une personne vérifie ce qui compte."}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Paiement reçu et rapproché", "send": "Automatique", "when": "Le jour du paiement", "lcap": "Transactionnel", "files": "Reçu (PDF)"}}'::jsonb, 'Reçu : loyer d’octobre payé', 'Merci! 1 385 $ reçus le 1er octobre.', array['prenom', 'lignes', 'total', 'date_paiement', 'numero_recu']::text[], 'Paiement reçu et rapproché', 'auto', false, 'transactional', false, false)
