insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-10', 'Locataires', 'Avis de renouvellement de bail', null, '{"subject": "Avis de renouvellement de votre bail : {adresse_logement}", "pre": "Votre réponse est attendue dans le mois suivant la réception.", "label": "Avis officiel", "icon": "history", "eyebrow": "Avis de modification du bail", "title": "Votre bail sera renouvelé le {date_renouvellement}", "intro": "{formule}, votre bail se termine le {date_fin_bail}. Nous vous proposons de le renouveler pour {duree}, aux conditions suivantes.", "blocks": [["table", {"head": ["Condition", "Nouveau bail"], "rows": [["Durée", "{duree}, dès le {date_renouvellement}"], ["Loyer mensuel", "{loyer_ligne}"], ["Autres conditions", "{autres_conditions}"]]}], ["notice", {"k": "legal", "title": "Vous avez {delai_reponse} pour répondre", "t": "Vous pouvez accepter, refuser la modification ou quitter le logement. Sans réponse dans ce délai, vous êtes réputé avoir accepté (art. 1945 C.c.Q.)."}]], "cta": {"l": "Répondre à l’avis", "href": "{lien_reponse}", "link": "Répondez aussi simplement à ce courriel."}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Fenêtre d’avis ouverte (3 à 6 mois avant la fin du bail)", "send": "Après approbation (processus Renouvellement)", "when": "Jour ouvrable, 9 h", "lcap": "Transactionnel (avis légal)", "files": "Avis de modification du bail (PDF)"}, "exemple": {"formule": "Monsieur Gagnon", "adresse_logement": "1180, Cartier — 3", "date_fin_bail": "31 mars 2027", "date_renouvellement": "1er avril 2027", "duree": "12 mois", "loyer_ligne": "1 284 $ (actuel : 1 245 $)", "autres_conditions": "Inchangées", "delai_reponse": "un mois", "lien_reponse": "https://app.leaselane.ca/?p=locataire", "gestionnaire": "Julie N.", "initiales_gestionnaire": "JN"}}'::jsonb, 'Avis de renouvellement de votre bail : {adresse_logement}', 'Votre réponse est attendue dans le mois suivant la réception.', array['adresse_logement', 'autres_conditions', 'date_fin_bail', 'date_renouvellement', 'delai_reponse', 'duree', 'formule', 'gestionnaire', 'initiales_gestionnaire', 'lien_reponse', 'loyer_ligne']::text[], 'Fenêtre d’avis ouverte (3 à 6 mois avant la fin du bail)', 'after_approval', false, 'legal', false, true)
