insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-11', 'Locataires', 'Document à signer', null, '{"subject": "Votre {type_document} est prêt à signer", "pre": "Signature électronique sécurisée, en 5 minutes.", "label": "Signature", "icon": "pencil", "eyebrow": "Signature", "title": "Votre {type_document} est prêt à signer", "intro": "{prenom}, voici votre {type_document} : {document}. Lisez-le, puis signez en ligne : c’est sécurisé et légal.", "blocks": [["doc", {"name": "{document}", "meta": "{details_document}", "kind": "eZsign"}], ["steps", {"rows": [[1, "Envoyé par Lease Lane", "{date_envoi}"], [2, "Votre signature", "aujourd’hui"], [0, "Copie signée envoyée à tous", ""]]}]], "cta": {"l": "Lire et signer", "href": "{lien_signature}", "link": "Une question sur une clause? Répondez à ce courriel."}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Enveloppe eZsign créée", "send": "Automatique · relance tous les 2 jours, 3 fois au plus", "when": "Entre 8 h et 22 h", "lcap": "Transactionnel"}}'::jsonb, 'Votre {type_document} est prêt à signer', 'Signature électronique sécurisée, en 5 minutes.', array['date_envoi', 'details_document', 'document', 'gestionnaire', 'initiales_gestionnaire', 'lien_signature', 'prenom', 'type_document']::text[], 'Enveloppe eZsign créée', 'auto', false, 'transactional', false, true)
