insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-12', 'Locataires', 'Cession acceptée', null, '{"subject": "Votre demande de {type_demande} est acceptée", "pre": "{cessionnaire} : à compter du {date_debut}.", "label": "Cession de bail", "icon": "check", "eyebrow": "Cession de bail", "title": "Votre demande de {type_demande} est acceptée", "intro": "{prenom}, le propriétaire accepte votre demande pour {cessionnaire} au {adresse_logement}, à compter du {date_debut}.", "blocks": [["steps", {"rows": [[1, "Demande reçue", "{date_demande}"], [1, "Vérifications", "{verification}"], [1, "Accord du propriétaire", "{date_accord}"], [2, "Signature de l’avenant", "vous, {cessionnaire} et le propriétaire"], [0, "Remise des clés", "à convenir avec votre gestionnaire"]]}], ["notice", {"k": "info", "title": "Ce qui change pour vous", "t": "{changement}"}]], "cta": {"l": "Signer l’avenant", "href": "{lien_avenant}"}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Cession acceptée (Cessions et sous-locations)", "send": "Après la décision du propriétaire", "when": "Jour ouvrable, entre 9 h et 17 h", "lcap": "Transactionnel (avis légal)", "files": "Avenant de cession (eZsign)"}}'::jsonb, 'Votre demande de {type_demande} est acceptée', '{cessionnaire} : à compter du {date_debut}.', array['adresse_logement', 'cessionnaire', 'changement', 'date_accord', 'date_debut', 'date_demande', 'gestionnaire', 'initiales_gestionnaire', 'lien_avenant', 'prenom', 'type_demande', 'verification']::text[], 'Cession acceptée (Cessions et sous-locations)', 'after_approval', false, 'legal', false, true)
