insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-13', 'Locataires', 'Cession refusée', null, '{"subject": "Votre demande de {type_demande} : réponse du propriétaire", "pre": "La demande pour {cessionnaire} est refusée pour un motif sérieux.", "label": "Cession de bail", "icon": "close", "eyebrow": "Cession de bail", "title": "Votre demande de {type_demande} est refusée", "intro": "{prenom}, le propriétaire ne peut accepter votre demande pour {cessionnaire}. La loi exige un motif sérieux ; le voici.", "blocks": [["quote", {"t": "{motif}", "by": "Motif du propriétaire"}], ["notice", {"k": "legal", "title": "Vos options", "t": "Vous pouvez proposer une autre personne ou contester ce refus au Tribunal administratif du logement. Votre bail reste en vigueur d’ici là."}]], "cta": {"l": "Proposer une autre personne", "href": "{lien_portail}", "link": "Répondre à Lease Lane"}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Refus enregistré avec motif (Cessions et sous-locations)", "send": "Après approbation humaine", "when": "Dans les 15 jours suivant la demande (art. 1871 C.c.Q.)", "lcap": "Transactionnel (avis légal)", "note": "Le motif est saisi par une personne. Cléo ne rédige jamais seule un motif de refus."}}'::jsonb, 'Votre demande de {type_demande} : réponse du propriétaire', 'La demande pour {cessionnaire} est refusée pour un motif sérieux.', array['cessionnaire', 'gestionnaire', 'initiales_gestionnaire', 'lien_portail', 'motif', 'prenom', 'type_demande']::text[], 'Refus enregistré avec motif (Cessions et sous-locations)', 'after_approval', false, 'legal', false, true)
