insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-14', 'Locataires', 'Consentement à une enquête de crédit', null, '{"subject": "Votre consentement pour une enquête de crédit", "pre": "Nécessaire pour étudier votre candidature au {adresse_logement}.", "label": "Candidature", "icon": "shield", "eyebrow": "Candidature", "title": "Votre consentement est nécessaire", "intro": "{prenom}, pour étudier votre candidature, nous devons vérifier votre dossier de crédit auprès d’Ozeille. Nous ne le ferons qu’avec votre accord.", "blocks": [["bullets", {"items": ["Ce que nous consultons : cote de crédit, historique de paiement, dossiers au TAL", "Qui le voit : la gestionnaire responsable seulement", "Combien de temps : le rapport est supprimé après 6 mois", "Sans frais pour vous"]}], ["notice", {"k": "legal", "ic": "shield", "title": "Loi 25", "t": "Vous pouvez retirer votre consentement en tout temps avant l’enquête et demander à consulter le rapport."}]], "cta": {"l": "Donner mon consentement", "href": "{lien_consentement}", "link": "Refuser : la candidature ne pourra pas être étudiée", "linkHref": "{lien_consentement}"}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Candidature reçue (logement à louer)", "send": "Automatique", "when": "Immédiat, entre 8 h et 22 h", "lcap": "Transactionnel", "note": "Consentement explicite, daté et inscrit au journal (Loi 25). Aucune enquête sans lui."}}'::jsonb, 'Votre consentement pour une enquête de crédit', 'Nécessaire pour étudier votre candidature au {adresse_logement}.', array['adresse_logement', 'gestionnaire', 'initiales_gestionnaire', 'lien_consentement', 'prenom']::text[], 'Candidature reçue (logement à louer)', 'auto', false, 'transactional', false, true)
