insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-15', 'Locataires', 'Visite confirmée', 'Lease Lane : visite confirmée jeudi 15 oct. à 10 h, 640, 3e Avenue (sonnez au 4). Répondez 2 pour changer l’heure.', '{"subject": "Visite confirmée : jeudi 10 h au 640, 3e Avenue", "pre": "Camille D. vous accueillera. Ajoutez la visite à votre agenda.", "label": "Visite", "icon": "calendar", "eyebrow": "Visite", "title": "Votre visite est confirmée", "intro": "Émilie, Camille D. vous fera visiter le 4½ du 640, 3e Avenue — 4.", "blocks": [["event", {"mon": "OCT.", "day": "15", "time": "Jeudi 15 octobre · 10 h", "place": "640, 3e Avenue, Limoilou · sonnez au 4"}], ["bullets", {"items": ["Prévoyez 20 minutes", "Apportez une pièce d’identité si vous souhaitez postuler sur place"]}]], "cta": {"l": "Ajouter à mon agenda", "link": "Changer l’heure"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare les messages ; une personne vérifie ce qui compte."}, "foot": {"reason": "Vous recevez ce courriel parce que vous avez réservé une visite avec Lease Lane."}, "spec": {"trigger": "Visite réservée (Cléo ou équipe)", "send": "Automatique · rappel la veille à 18 h", "when": "Immédiat", "lcap": "Transactionnel"}}'::jsonb, 'Visite confirmée : jeudi 10 h au 640, 3e Avenue', 'Camille D. vous accueillera. Ajoutez la visite à votre agenda.', array['prenom', 'date_visite', 'heure', 'adresse', 'guide']::text[], 'Visite réservée (Cléo ou équipe)', 'auto', false, 'transactional', false, false)
