insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-16', 'Locataires', 'Candidature acceptée', null, '{"subject": "Bonne nouvelle : votre candidature est acceptée", "pre": "Signez votre bail d’ici le 9 octobre pour garder le logement.", "label": "Candidature", "icon": "star", "eyebrow": "Candidature", "title": "Bienvenue au 420, Saint-Joseph Est, William!", "intro": "La propriétaire a accepté votre candidature pour le 4½ (1 240 $ par mois, dès le 1er décembre).", "blocks": [["steps", {"rows": [[1, "Candidature", "acceptée le 6 octobre"], [2, "Signature du bail", "d’ici le 9 octobre"], [0, "Accès au portail", "dès la signature"], [0, "Remise des clés", "1er décembre"]]}], ["notice", {"k": "info", "title": "Pourquoi un délai?", "t": "Le logement vous est réservé jusqu’au 9 octobre. Après cette date, il pourrait être offert à une autre personne."}]], "cta": {"l": "Signer mon bail"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous avez déposé une candidature auprès de Lease Lane."}, "spec": {"trigger": "Candidature acceptée par le propriétaire", "send": "Automatique", "when": "Jour ouvrable, entre 9 h et 20 h", "lcap": "Transactionnel"}}'::jsonb, 'Bonne nouvelle : votre candidature est acceptée', 'Signez votre bail d’ici le 9 octobre pour garder le logement.', array['prenom', 'adresse_logement', 'loyer', 'date_debut', 'date_limite_signature']::text[], 'Candidature acceptée par le propriétaire', 'auto', false, 'transactional', false, false)
