insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-17', 'Locataires', 'Rappel de preuve d’assurance', null, '{"subject": "Votre preuve d’assurance habitation 2026-2027", "pre": "Téléversez-la avant le 31 octobre, en 2 minutes.", "label": "Rappel annuel", "icon": "shield", "eyebrow": "Rappel annuel", "title": "Votre preuve d’assurance arrive à échéance", "intro": "Karine, votre bail exige une assurance responsabilité civile. Celle de votre dossier expire le 31 octobre.", "blocks": [["kv", {"rows": [["Assurance au dossier", "expire le 31 octobre 2026"], ["À fournir", "Preuve 2026-2027"]]}]], "cta": {"l": "Téléverser ma preuve"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare les messages ; une personne vérifie ce qui compte."}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Assurance qui expire dans 21 jours", "send": "Automatique · rappel 7 jours avant", "when": "9 h", "lcap": "Transactionnel"}}'::jsonb, 'Votre preuve d’assurance habitation 2026-2027', 'Téléversez-la avant le 31 octobre, en 2 minutes.', array['prenom', 'date_expiration', 'lien_televersement']::text[], 'Assurance qui expire dans 21 jours', 'auto', false, 'transactional', false, false)
