insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-18', 'Locataires', 'Loi 25, demande d’accès reçue', null, '{"subject": "Votre demande d’accès à vos renseignements", "pre": "Reçue le 10 octobre · réponse au plus tard le 9 novembre.", "label": "Loi 25", "icon": "shield", "eyebrow": "Loi 25", "title": "Nous avons reçu votre demande d’accès", "intro": "Léa, vous avez demandé une copie des renseignements personnels que Lease Lane détient à votre sujet. Nous vous répondrons d’ici le 9 novembre.", "blocks": [["meter", {"label": "Délai légal de 30 jours", "value": "28 jours restants", "r": 0.06666666666666667, "cap": "Reçue le 10 octobre · réponse au plus tard le 9 novembre"}], ["bullets", {"items": ["Vous recevrez : coordonnées, bail, paiements, demandes et échanges", "Format : PDF et tableur, protégés par un mot de passe", "Sans frais"]}]], "cta": {"l": "Suivre ma demande"}, "sign": {"ini": "SP", "name": "Steven Paradis", "role": "Responsable de la protection des renseignements personnels"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Demande d’accès reçue (portail ou courriel)", "send": "Automatique (accusé de réception)", "when": "Immédiat", "lcap": "Transactionnel (obligation légale)", "note": "Réponse dans les 30 jours (Loi sur la protection des renseignements personnels dans le secteur privé, art. 32)."}}'::jsonb, 'Votre demande d’accès à vos renseignements', 'Reçue le 10 octobre · réponse au plus tard le 9 novembre.', array['prenom', 'date_reception', 'date_limite']::text[], 'Demande d’accès reçue (portail ou courriel)', 'auto', false, 'legal', false, false)
