insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-19', 'Locataires', 'Loi 25, renseignements prêts', null, '{"subject": "Vos renseignements sont prêts à télécharger", "pre": "Lien valable 7 jours · mot de passe envoyé par SMS.", "label": "Loi 25", "icon": "download", "eyebrow": "Loi 25", "title": "Vos renseignements sont prêts", "intro": "Léa, voici la copie de vos renseignements personnels, comme demandé le 10 octobre.", "blocks": [["doc", {"name": "Renseignements · Léa Bouchard", "meta": "PDF et tableur · 2,4 Mo · protégé", "kind": "ZIP"}], ["notice", {"k": "info", "ic": "lock", "title": "Sécurité", "t": "Le mot de passe vous est envoyé par SMS. Le lien expire le 23 octobre."}]], "cta": {"l": "Télécharger mes renseignements", "link": "Corriger un renseignement"}, "sign": {"ini": "SP", "name": "Steven Paradis", "role": "Responsable de la protection des renseignements personnels"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Export préparé et vérifié par le responsable", "send": "Après approbation humaine", "when": "Jour ouvrable", "lcap": "Transactionnel (obligation légale)", "files": "Archive protégée (lien, jamais en pièce jointe)"}}'::jsonb, 'Vos renseignements sont prêts à télécharger', 'Lien valable 7 jours · mot de passe envoyé par SMS.', array['prenom', 'lien_telechargement', 'date_expiration']::text[], 'Export préparé et vérifié par le responsable', 'after_approval', false, 'legal', false, false)
