insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-20', 'Locataires', 'Avis de travaux dans l’immeuble', 'Lease Lane : coupure d’eau au 640, 3e Avenue mardi 20 oct., de 9 h à 12 h. Prévoyez de l’eau la veille.', '{"subject": "Coupure d’eau mardi de 9 h à 12 h : 640, 3e Avenue", "pre": "Remplacement d’une valve principale. Prévoyez de l’eau la veille.", "label": "Avis aux locataires", "icon": "drop", "eyebrow": "Avis aux locataires", "title": "Coupure d’eau mardi matin", "intro": "Pour remplacer une valve principale, l’eau sera coupée dans tout l’immeuble le mardi 20 octobre, de 9 h à 12 h.", "blocks": [["event", {"mon": "OCT.", "day": "20", "time": "Mardi 20 octobre · 9 h à 12 h", "place": "640, 3e Avenue · tous les logements"}], ["bullets", {"items": ["Remplissez quelques bouteilles d’eau la veille", "Évitez la laveuse et le lave-vaisselle pendant la coupure", "Au retour, l’eau peut être trouble quelques minutes : laissez-la couler"]}]], "cta": {"l": "Poser une question à Cléo"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Bon de travail qui touche tout l’immeuble", "send": "Après approbation", "when": "Au moins 48 h avant, entre 8 h et 22 h", "lcap": "Transactionnel"}}'::jsonb, 'Coupure d’eau mardi de 9 h à 12 h : 640, 3e Avenue', 'Remplacement d’une valve principale. Prévoyez de l’eau la veille.', array['adresse_immeuble', 'date', 'plage_horaire', 'travaux']::text[], 'Bon de travail qui touche tout l’immeuble', 'after_approval', false, 'transactional', false, false)
