insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('LOC-21', 'Locataires', 'Paiement en ligne indisponible', 'Lease Lane : le paiement en ligne est interrompu depuis 8 h 40. Aucun rappel de retard ne partira. Nous vous écrirons au retour du service.', '{"subject": "Paiement en ligne : interruption en cours", "pre": "Aucun rappel de retard ne partira pendant l’interruption.", "label": "Paiements", "icon": "card", "eyebrow": "Avis de service", "title": "Le paiement en ligne est momentanément indisponible", "intro": "Chloé, depuis 8 h 40, le paiement du loyer dans votre Espace locataire ne fonctionne pas. Nous y travaillons.", "blocks": [["kv", {"rows": [["Depuis", "8 h 40"], ["Service touché", "Paiement en ligne seulement"], ["Prélèvements automatiques", "Non touchés"]]}], ["notice", {"k": "info", "title": "Votre loyer est dû aujourd’hui?", "t": "Payez au retour du service : nous vous écrirons. Aucun rappel de retard ne partira pendant l’interruption."}], ["p", {"t": "Une question? Écrivez à Cléo, jour et nuit."}]], "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare ; une personne décide."}, "foot": {"reason": "Vous recevez ce courriel parce que vous êtes locataire d’un logement géré par Lease Lane."}, "spec": {"trigger": "Paiement en ligne interrompu plus de 15 minutes, la veille ou le jour d’une échéance", "send": "Après approbation", "when": "Dès l’approbation", "lcap": "Transactionnel (avis de service)", "note": "Un second avis part au retour du service. Le bandeau de l’Espace locataire affiche le même message."}}'::jsonb, 'Paiement en ligne : interruption en cours', 'Aucun rappel de retard ne partira pendant l’interruption.', array['prenom', 'depuis', 'service']::text[], 'Paiement en ligne interrompu plus de 15 minutes, la veille ou le jour d’une échéance', 'after_approval', false, 'transactional', false, false)
