insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-01', 'Propriétaires (prospects)', 'Proposition de gestion', null, '{"subject": "Notre proposition pour le 1260 et le 1272, 3e Avenue", "pre": "6 portes, gestion complète, 430 $ par mois · valable 30 jours", "label": "Proposition", "icon": "file", "eyebrow": "Proposition de gestion", "title": "Notre proposition pour vos 6 portes de Limoilou", "intro": "Mathieu, merci de votre confiance. Voici comment nous gérerions le 1260 et le 1272, 3e Avenue, dès le 1er décembre.", "blocks": [["table", {"head": ["Service", "Inclus"], "rows": [["Location et sélection des locataires", "Oui"], ["Perception des loyers et relances", "Oui"], ["Entretien, urgences 24 h sur 24", "Oui"], ["Relevés mensuels et portail", "Oui"]], "total": ["Honoraires", "430 $ par mois"]}], ["quote", {"t": "Vos deux immeubles sont voisins de deux autres que nous gérons : les visites et les interventions seront plus rapides.", "by": "Julie N., gestionnaire"}], ["doc", {"name": "Proposition · Investissements Roy", "meta": "8 pages · valable jusqu’au 14 novembre"}]], "cta": {"l": "Accepter la proposition", "link": "Planifier un appel avec Julie"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous avez demandé une proposition à Lease Lane.", "commercial": true}, "spec": {"trigger": "Offre de services approuvée (Ventes › Cadrage du mandat)", "send": "Après approbation · relance après 3 jours sans réponse", "when": "Jour ouvrable, 9 h", "lcap": "Commercial · désabonnement obligatoire", "note": "Arrêt des relances dès que le propriétaire répond.", "files": "Proposition de gestion (PDF)"}}'::jsonb, 'Notre proposition pour le 1260 et le 1272, 3e Avenue', '6 portes, gestion complète, 430 $ par mois · valable 30 jours', array['prenom', 'immeubles', 'portes', 'honoraires', 'date_validite']::text[], 'Offre de services approuvée (Ventes › Cadrage du mandat)', 'after_approval', false, 'commercial', true, false)
