insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-02', 'Propriétaires', 'Bienvenue, mandat signé', null, '{"subject": "Bienvenue chez Lease Lane : vos 30 premiers jours", "pre": "Votre portail propriétaire est actif.", "label": "Portail propriétaire", "icon": "building", "eyebrow": "Bienvenue", "title": "Bienvenue, {prenom} : on s’occupe du reste", "intro": "Votre mandat de gestion est signé. Voici ce qui se passe dans les 30 prochains jours.", "blocks": [["steps", {"rows": [[1, "Mandat signé", "{date_signature}"], [2, "Inventaire des logements", "{etape_inventaire}"], [0, "Avis aux locataires", "nouvelles coordonnées de paiement"], [0, "Premier relevé mensuel", "{date_premier_releve}"]]}]], "cta": {"l": "Ouvrir mon portail", "href": "{lien_portail}"}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Mandat signé (eZsign)", "send": "Automatique", "when": "Immédiat, entre 8 h et 22 h", "lcap": "Transactionnel"}}'::jsonb, 'Bienvenue chez Lease Lane : vos 30 premiers jours', 'Votre portail propriétaire est actif.', array['date_premier_releve', 'date_signature', 'etape_inventaire', 'gestionnaire', 'initiales_gestionnaire', 'lien_portail', 'prenom']::text[], 'Mandat signé (eZsign)', 'auto', false, 'transactional', false, true)
