insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-03', 'Propriétaires', 'Accord requis, dépense', 'Lease Lane : votre accord est requis pour le chauffe-eau du 640, 3e Av. (1 375 $). Approuver : leaselane.ca/o/2H', '{"subject": "Votre accord : remplacement du chauffe-eau (1 375 $)", "pre": "3 soumissions comparées · Cléo recommande Plomberie Capitale.", "label": "Accord requis", "icon": "dollar", "eyebrow": "Accord requis", "title": "Votre accord est requis pour une dépense de 1 375 $", "intro": "Le chauffe-eau du 640, 3e Avenue — 3 fuit et doit être remplacé. Nous avons obtenu 3 soumissions.", "blocks": [["compare", {"head": "Soumissions reçues · le trait marque le budget de 1 400 $", "rows": [["Plomberie Capitale", 1375, "1 375 $", 1], ["Les Plombiers de Lévis", 1290, "1 290 $", 0], ["Thermo-Pro", 1520, "1 520 $", 0]], "ref": [1400, "budget"]}], ["quote", {"t": "Plomberie Capitale peut intervenir demain, sous le budget. Les Plombiers de Lévis sont moins chers, mais disponibles dans 4 jours seulement.", "by": "Recommandation de Cléo, vérifiée par Julie N."}]], "cta": {"l": "Approuver Plomberie Capitale", "link": "Choisir une autre soumission"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Dépense de plus de 500 $ à approuver", "send": "Automatique · relance après 24 h (SMS et portail)", "when": "Entre 8 h et 20 h", "lcap": "Transactionnel"}}'::jsonb, 'Votre accord : remplacement du chauffe-eau (1 375 $)', '3 soumissions comparées · Cléo recommande Plomberie Capitale.', array['prenom', 'travaux', 'adresse_logement', 'soumissions', 'recommandation']::text[], 'Dépense de plus de 500 $ à approuver', 'auto', false, 'transactional', false, false)
