insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-04', 'Propriétaires', 'Accord requis, cession', null, '{"subject": "Votre accord : {type_demande} au {adresse_logement}", "pre": "Réponse requise d’ici le {date_limite} (délai légal de 15 jours).", "label": "Accord requis", "icon": "users", "eyebrow": "Accord requis", "title": "{titre_demande}", "intro": "La loi vous donne 15 jours pour répondre. Sans réponse, la demande est réputée acceptée (art. 1871 C.c.Q.).", "blocks": [["kv", {"rows": [["Logement", "{logement_ligne}"], ["Nouvelle personne", "{cessionnaire_ligne}"], ["Solvabilité", "{solvabilite}"], ["À compter du", "{date_debut}"]]}], ["meter", {"label": "Délai pour répondre", "value": "{jours_restants}", "r": "{ratio_delai}", "cap": "Demande reçue le {date_demande} · réponse au plus tard le {date_limite}"}], ["notice", {"k": "legal", "title": "Refuser?", "t": "Un refus doit reposer sur un motif sérieux, par exemple une solvabilité insuffisante. Nous rédigerons la réponse avec vous."}]], "cta": {"l": "Accepter", "href": "{lien_reponse}", "link": "Refuser avec un motif", "linkHref": "{lien_reponse}"}, "sign": {"ini": "{initiales_gestionnaire}", "name": "{gestionnaire}", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Demande de cession vérifiée (fiche et solvabilité)", "send": "Automatique · relance tous les 3 jours", "when": "Entre 8 h et 20 h", "lcap": "Transactionnel"}}'::jsonb, 'Votre accord : {type_demande} au {adresse_logement}', 'Réponse requise d’ici le {date_limite} (délai légal de 15 jours).', array['adresse_logement', 'cessionnaire_ligne', 'date_debut', 'date_demande', 'date_limite', 'gestionnaire', 'initiales_gestionnaire', 'jours_restants', 'lien_reponse', 'logement_ligne', 'ratio_delai', 'solvabilite', 'titre_demande', 'type_demande']::text[], 'Demande de cession vérifiée (fiche et solvabilité)', 'auto', false, 'transactional', false, true)
