insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-05', 'Propriétaires', 'Relevé mensuel', null, '{"subject": "Votre relevé de septembre : 640, 3e Avenue", "pre": "Revenus 9 840 $ · dépenses 1 643 $ · versement 8 197 $", "label": "Relevé mensuel", "icon": "chart", "eyebrow": "Relevé mensuel", "title": "Septembre : 8 197 $ versés", "intro": "Tous les loyers de septembre ont été perçus. Voici le détail de votre immeuble.", "blocks": [["table", {"head": ["Poste", "Montant"], "rows": [["Loyers perçus (8 logements)", "9 840 $"], ["Entretien et réparations", "−865 $"], ["Honoraires (6 % des loyers, 10 % des travaux)", "−677 $"], ["TPS et TVQ sur les honoraires", "−101 $"]], "total": ["Versé dans votre compte", "8 197 $"]}], ["bars", {"v": [8340, 8110, 8470, 8250, 7590, 8197], "lab": ["avr.", "mai", "juin", "juil.", "août", "sept."], "top": "8 197 $"}], ["doc", {"name": "Relevé · septembre 2026", "meta": "4 pages · factures jointes"}]], "cta": {"l": "Voir le relevé détaillé"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Clôture du mois (rapprochement terminé)", "send": "Automatique, après vérification", "when": "Le 5 du mois, 9 h", "lcap": "Transactionnel", "files": "Relevé mensuel (PDF) et factures"}}'::jsonb, 'Votre relevé de septembre : 640, 3e Avenue', 'Revenus 9 840 $ · dépenses 1 643 $ · versement 8 197 $', array['prenom', 'immeuble', 'mois', 'revenus', 'depenses', 'versement']::text[], 'Clôture du mois (rapprochement terminé)', 'auto', false, 'transactional', false, false)
