insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-06', 'Propriétaires', 'Versement effectué', null, '{"subject": "Versement de 8 197 $ effectué", "pre": "Déposé dans votre compte se terminant par 7731.", "label": "Versement", "icon": "wallet", "eyebrow": "Versement", "title": "8 197 $ ont été déposés dans votre compte", "blocks": [["kv", {"rows": [["Montant", "8 197 $"], ["Date", "5 octobre 2026"], ["Compte", "•••• 7731"], ["Période", "Septembre 2026"]]}]], "cta": {"l": "Voir le relevé"}, "sign": {"cleo": true, "name": "Cléo, assistante de Lease Lane", "role": "Je prépare ; une personne décide."}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Virement envoyé à la banque", "send": "Automatique", "when": "Le jour du virement", "lcap": "Transactionnel"}}'::jsonb, 'Versement de 8 197 $ effectué', 'Déposé dans votre compte se terminant par 7731.', array['prenom', 'montant', 'date', 'compte_masque', 'periode']::text[], 'Virement envoyé à la banque', 'auto', false, 'transactional', false, false)
