insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-07', 'Propriétaires', 'Logement en location', null, '{"subject": "Le 4½ du 640, 3e Avenue est en ligne", "pre": "Photos retouchées, visite 3D et annonce publiées sur 3 sites.", "label": "Mise en marché", "icon": "globe", "eyebrow": "Mise en marché", "title": "Votre logement est en location", "blocks": [["photo", {"f": "montcalm-cartier.jpg"}], ["kv", {"rows": [["Loyer affiché", "1 450 $ par mois"], ["Libre le", "1er décembre"], ["Publié sur", "Lease Lane, Marketplace, Kijiji"]]}], ["p", {"t": "Nous vous écrirons dès qu’une candidature sérieuse arrive. Objectif : loué en 21 jours."}]], "cta": {"l": "Voir l’annonce"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Annonce publiée (Mise en marché)", "send": "Automatique", "when": "Jour ouvrable", "lcap": "Transactionnel"}}'::jsonb, 'Le 4½ du 640, 3e Avenue est en ligne', 'Photos retouchées, visite 3D et annonce publiées sur 3 sites.', array['prenom', 'logement', 'loyer', 'date_libre', 'canaux']::text[], 'Annonce publiée (Mise en marché)', 'auto', false, 'transactional', false, false)
