insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-08', 'Propriétaires', 'Locataire recommandé', null, '{"subject": "Candidature retenue pour le 640, 3e Avenue — 4", "pre": "Émilie Gagnon · solvabilité très bonne · votre accord en un clic", "label": "Candidature", "icon": "user", "eyebrow": "Candidature", "title": "Nous recommandons Émilie Gagnon", "blocks": [["kv", {"rows": [["Revenu annuel", "58 000 $"], ["Loyer sur revenu", "30 %"], ["Cote de crédit", "Très bonne"], ["Références", "2 vérifiées"]]}], ["quote", {"t": "Revenu stable depuis 4 ans, aucun dossier au TAL et des références positives de son propriétaire actuel.", "by": "Julie N., gestionnaire"}]], "cta": {"l": "Accepter Émilie Gagnon", "link": "Voir les 3 autres candidatures"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Candidature recommandée par la gestionnaire", "send": "Après approbation humaine", "when": "Entre 8 h et 20 h", "lcap": "Transactionnel", "note": "Aucun renseignement sensible en clair : le rapport complet reste dans le portail (Loi 25)."}}'::jsonb, 'Candidature retenue pour le 640, 3e Avenue — 4', 'Émilie Gagnon · solvabilité très bonne · votre accord en un clic', array['prenom', 'candidat', 'revenu', 'ratio', 'cote']::text[], 'Candidature recommandée par la gestionnaire', 'after_approval', false, 'transactional', false, false)
