insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-09', 'Propriétaires', 'Urgence en cours', 'Lease Lane : urgence au 420, Saint-Joseph E. (détecteur de fumée). Électricien sur place, aucun dommage. Suivi : leaselane.ca/u/5C', '{"subject": "Urgence au 420, Saint-Joseph Est : détecteur de fumée", "pre": "Électrique Duval est sur place. Aucun blessé, aucun dommage.", "label": "Urgence", "icon": "siren", "eyebrow": "Urgence en cours", "title": "Un détecteur de fumée défectueux est en remplacement", "intro": "Le locataire du logement 5 a signalé à 11 h 46 un détecteur qui sonnait sans arrêt. Électrique Duval est sur place depuis 12 h 04.", "accent": "urgent", "blocks": [["steps", {"rows": [[1, "Signalement reçu", "11 h 46, par Cléo"], [1, "Électricien sur place", "12 h 04"], [2, "Remplacement", "en cours"], [0, "Rapport et facture", "aujourd’hui"]]}], ["notice", {"k": "info", "title": "Coût estimé", "t": "Environ 180 $, sous le seuil de 500 $ : aucune approbation n’est nécessaire."}]], "cta": {"l": "Suivre l’intervention"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Demande classée « urgence »", "send": "Automatique", "when": "Immédiat, à toute heure", "lcap": "Transactionnel"}}'::jsonb, 'Urgence au 420, Saint-Joseph Est : détecteur de fumée', 'Électrique Duval est sur place. Aucun blessé, aucun dommage.', array['prenom', 'adresse', 'probleme', 'fournisseur', 'etapes']::text[], 'Demande classée « urgence »', 'auto', true, 'transactional', false, false)
