insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-10', 'Propriétaires', 'Recouvrement en cours', null, '{"subject": "Loyer impayé au 640, 3e Avenue — 7 : mise en demeure envoyée", "pre": "1 195 $ dus · prochaine étape possible le 22 octobre", "label": "Recouvrement", "icon": "scale", "eyebrow": "Recouvrement", "title": "Une mise en demeure a été envoyée", "blocks": [["steps", {"rows": [[1, "Rappel par SMS", "2 octobre"], [1, "Courriel de relance", "8 octobre"], [1, "Mise en demeure", "13 octobre"], [0, "Demande au TAL", "possible dès le 22 octobre"]]}], ["p", {"t": "Nous vous consulterons avant de déposer une demande au Tribunal administratif du logement."}]], "cta": {"l": "Voir le dossier"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Mise en demeure envoyée", "send": "Automatique", "when": "Jour ouvrable", "lcap": "Transactionnel", "note": "Le nom du locataire n’apparaît pas dans l’objet : seulement le logement (Loi 25)."}}'::jsonb, 'Loyer impayé au 640, 3e Avenue — 7 : mise en demeure envoyée', '1 195 $ dus · prochaine étape possible le 22 octobre', array['prenom', 'logement', 'montant', 'etapes', 'date_prochaine_etape']::text[], 'Mise en demeure envoyée', 'auto', false, 'transactional', false, false)
