insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-11', 'Propriétaires (prospects)', 'Portée du mandat à confirmer', null, '{"subject": "Avant notre proposition : la portée à confirmer", "pre": "4 services inclus, 2 exclus, 2 reportés · deux minutes pour vérifier", "label": "Proposition", "icon": "layers", "eyebrow": "Cadrage du mandat", "title": "Voici ce que nous avons compris", "intro": "Mathieu, avant notre proposition du 14 octobre, confirmez ce que vous voulez confier à Lease Lane pour le 1260 et le 1272, 3e Avenue.", "blocks": [["quote", {"t": "Je veux arrêter de gérer les appels de nuit.", "by": "Vous, au rendez-vous du 8 octobre"}], ["bullets", {"items": ["Inclus : perception des loyers et recouvrement, entretien et urgences jour et nuit, location des logements vacants, relevés mensuels.", "Exclus : rénovations majeures (cadrées à part, projet par projet) et la vente du 1272.", "Reporté : déneigement (votre contrat court jusqu’au 30 avril 2027) et location à court terme (à revoir en mars 2027)."]}], ["notice", {"k": "info", "ic": "check", "title": "Vos exigences", "t": "Relevé avant le 5 de chaque mois · votre approbation au-delà de 500 $ · documents pour votre comptable en janvier."}]], "cta": {"l": "Confirmer la portée", "link": "Un élément à corriger? Répondez à ce courriel."}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous avez demandé une proposition de gestion à Lease Lane."}, "spec": {"trigger": "Cadrage prêt pour validation (Ventes › Cadrage du mandat)", "send": "Après approbation du responsable", "when": "Dès l’envoi", "lcap": "Transactionnel (réponse à une demande)", "note": "La portée confirmée devient l’annexe A du mandat de gestion."}}'::jsonb, 'Avant notre proposition : la portée à confirmer', '4 services inclus, 2 exclus, 2 reportés · deux minutes pour vérifier', array['prenom', 'immeubles', 'inclus', 'exclus', 'reporte', 'exigences', 'date_proposition']::text[], 'Cadrage prêt pour validation (Ventes › Cadrage du mandat)', 'after_approval', false, 'transactional', false, false)
