insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-12', 'Propriétaires', 'Portée des travaux à approuver', null, '{"subject": "Toiture du 640 : la portée des travaux à approuver", "pre": "Avant de demander des soumissions · budget estimé de 38 000 à 45 000 $", "label": "Projets", "icon": "building", "eyebrow": "Projet P-2026-04", "title": "Réfection de la toiture : la portée d’abord", "intro": "Marie-Josée, l’inspection du 2 octobre le confirme : la membrane posée en 1998 est en fin de vie. Approuvez ce que les soumissions devront couvrir, pour comparer les prix sur la même base.", "blocks": [["bullets", {"items": ["Inclus : membrane élastomère 2 couches, solins, réparation du plafond du 640 — 8.", "Exclus : puits de lumière, en bon état.", "Reporté : isolation de l’entretoit au printemps 2027 (subvention Rénoclimat à vérifier)."]}], ["kv", {"rows": [["Budget estimé", "38 000 à 45 000 $"], ["Soumissions", "3 couvreurs"], ["Travaux", "avant le 15 novembre"]]}], ["notice", {"k": "legal", "title": "Vos locataires", "t": "Le locataire du 640 — 8 recevra un avis de 24 heures avant l’inspection intérieure (art. 1931 C.c.Q.)."}]], "cta": {"l": "Approuver la portée", "link": "Une question? Répondez à ce courriel ou écrivez à Cléo."}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Cadrage d’un projet prêt (Maintenance › Projets)", "send": "Après approbation du gestionnaire", "when": "Dès l’envoi", "lcap": "Transactionnel", "note": "L’approbation est enregistrée dans l’Espace propriétaire et au journal.", "files": ["Rapport d’inspection du 2 oct. (PDF)"]}}'::jsonb, 'Toiture du 640 : la portée des travaux à approuver', 'Avant de demander des soumissions · budget estimé de 38 000 à 45 000 $', array['prenom', 'projet', 'immeuble', 'inclus', 'exclus', 'reporte', 'budget', 'lien_approbation']::text[], 'Cadrage d’un projet prêt (Maintenance › Projets)', 'after_approval', false, 'transactional', false, false)
