insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PRO-13', 'Propriétaires', 'Ajout au mandat', null, '{"subject": "Ajout à votre mandat : déneigement du stationnement", "pre": "Avenant · portée v1.3 · 45 $ par mois · à signer en ligne", "label": "Mandat", "icon": "pencil", "eyebrow": "Avenant au mandat", "title": "Ajouter le déneigement à votre mandat", "intro": "Marie-Josée, comme convenu, voici l’avenant qui ajoute le déneigement du stationnement du 640, 3e Avenue à votre mandat de gestion.", "blocks": [["kv", {"rows": [["Ajouté", "Déneigement du stationnement"], ["Prix", "45 $ par mois"], ["Début", "À la signature"], ["Version", "Portée v1.3 (remplace v1.2)"]]}], ["doc", {"name": "Avenant · portée v1.3", "meta": "1 page · à signer avec eZsign", "kind": "eZsign"}], ["p", {"t": "Le reste de votre mandat ne change pas. La portée à jour est dans votre Espace propriétaire, sous « Ce qui est inclus dans mon mandat »."}]], "cta": {"l": "Signer l’avenant"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que Lease Lane gère votre immeuble."}, "spec": {"trigger": "Avenant proposé (Clients › Portée du mandat)", "send": "Après approbation du gestionnaire", "when": "Dès l’envoi", "lcap": "Transactionnel", "note": "Relance eZsign tous les 2 jours, 3 fois au plus."}}'::jsonb, 'Ajout à votre mandat : déneigement du stationnement', 'Avenant · portée v1.3 · 45 $ par mois · à signer en ligne', array['prenom', 'ajout', 'prix', 'version', 'lien_signature']::text[], 'Avenant proposé (Clients › Portée du mandat)', 'after_approval', false, 'transactional', false, false)
