insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PSP-01', 'Prospects', 'Demande reçue (site web)', null, '{"subject": "Merci, Marc : votre demande est reçue", "pre": "Julie N. vous appellera d’ici demain midi.", "label": "Gestion immobilière", "icon": "check", "eyebrow": "Gestion immobilière", "title": "Merci pour votre demande", "intro": "Vous nous avez écrit au sujet de votre immeuble de 5 portes. Julie N., gestionnaire, vous appellera d’ici demain midi.", "blocks": [["steps", {"rows": [[1, "Demande reçue", "aujourd’hui, 11 h 58"], [2, "Appel avec Julie", "d’ici demain midi"], [0, "Visite de l’immeuble", ""], [0, "Proposition écrite", ""]]}]], "cta": {"l": "Choisir l’heure de l’appel"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous avez rempli le formulaire de leaselane.ca."}, "spec": {"trigger": "Formulaire du site soumis", "send": "Automatique", "when": "Immédiat", "lcap": "Transactionnel (réponse à une demande)"}}'::jsonb, 'Merci, Marc : votre demande est reçue', 'Julie N. vous appellera d’ici demain midi.', array['prenom', 'immeuble', 'gestionnaire', 'delai_appel']::text[], 'Formulaire du site soumis', 'auto', false, 'transactional', false, false)
