insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PSP-02', 'Prospects', 'Séquence, présentation (jour 0)', null, '{"subject": "Gestion de vos immeubles de Limoilou", "pre": "Une gestion locale pour vos 22 portes, sans engagement.", "label": "Gestion immobilière", "icon": "building", "eyebrow": "Gestion immobilière", "title": "Une gestion locale pour vos 22 portes de Limoilou", "intro": "Bonjour, nous gérons déjà deux immeubles voisins des vôtres. Voici ce que nos clients de Limoilou ont obtenu cette année.", "blocks": [["kv", {"rows": [["Logements loués en", "18 jours en moyenne"], ["Loyers perçus", "99,6 %"], ["Urgences prises en charge", "24 h sur 24"]]}], ["doc", {"name": "Étude de cas · Limoilou", "meta": "2 pages"}]], "cta": {"l": "Planifier un appel de 15 minutes", "link": "Pas intéressé? Se désabonner en un clic."}, "sign": {"ini": "LP", "name": "Laurence P.", "role": "Location et prospection · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vos coordonnées d’entreprise sont publiques. Un clic suffit pour ne plus rien recevoir.", "commercial": true}, "spec": {"trigger": "Ajout à la séquence, après révision humaine", "send": "Automatique, liste approuvée", "when": "Jour ouvrable, entre 9 h et 17 h ; jamais entre 22 h et 8 h", "lcap": "Commercial · consentement vérifié · désabonnement obligatoire", "note": "Arrêt dès qu’il y a une réponse ; 5 tentatives au plus."}}'::jsonb, 'Gestion de vos immeubles de Limoilou', 'Une gestion locale pour vos 22 portes, sans engagement.', array['entreprise', 'portes', 'quartier', 'etude_de_cas']::text[], 'Ajout à la séquence, après révision humaine', 'auto', false, 'commercial', true, false)
