insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PSP-03', 'Prospects', 'Séquence, suivi (jour 7)', null, '{"subject": "Re : gestion de vos immeubles de Limoilou", "pre": "Une question de 2 minutes : qui gère vos immeubles aujourd’hui?", "label": "Gestion immobilière", "icon": "message", "eyebrow": "Suivi", "title": "Une question rapide", "intro": "Bonjour, je reviens vers vous : gérez-vous vos 22 portes vous-même, ou avec un gestionnaire? Selon votre réponse, je vous enverrai une estimation adaptée, ou je ne vous écrirai plus.", "blocks": [], "cta": {"l": "Répondre en un clic", "link": "Ne plus recevoir nos messages"}, "sign": {"ini": "LP", "name": "Laurence P.", "role": "Location et prospection · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel à la suite de notre message du 13 octobre.", "commercial": true}, "spec": {"trigger": "Jour 7, seulement sans réponse", "send": "Automatique", "when": "Jour ouvrable, entre 9 h et 17 h", "lcap": "Commercial · désabonnement obligatoire"}}'::jsonb, 'Re : gestion de vos immeubles de Limoilou', 'Une question de 2 minutes : qui gère vos immeubles aujourd’hui?', array['entreprise', 'portes']::text[], 'Jour 7, seulement sans réponse', 'auto', false, 'commercial', true, false)
