insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PSP-04', 'Prospects', 'Séquence, dernier message (jour 14)', null, '{"subject": "Je ne vous écrirai plus après ce message", "pre": "Notre offre reste valable si vous changez d’idée.", "label": "Gestion immobilière", "icon": "flag", "eyebrow": "Dernier message", "title": "Merci de votre temps", "intro": "Bonjour, je ne vous relancerai plus. Si un jour vous cherchez un gestionnaire à Limoilou, il suffira de répondre à ce courriel.", "blocks": [], "cta": {"l": "Visiter leaselane.ca"}, "sign": {"ini": "LP", "name": "Laurence P.", "role": "Location et prospection · Lease Lane"}, "foot": {"reason": "Vous recevez ce dernier courriel à la suite de nos messages d’octobre.", "commercial": true}, "spec": {"trigger": "Jour 14, seulement sans réponse", "send": "Automatique", "when": "Jour ouvrable", "lcap": "Commercial · désabonnement obligatoire", "note": "Le contact sort de la séquence après ce message."}}'::jsonb, 'Je ne vous écrirai plus après ce message', 'Notre offre reste valable si vous changez d’idée.', array['entreprise']::text[], 'Jour 14, seulement sans réponse', 'auto', false, 'commercial', true, false)
