insert into comms.email_templates (code, audience, name, sms_text, contenu, subject, preheader, variables, trigger_event, send_mode, essential, lcap_category, unsubscribe_required, active) values ('PSP-05', 'Prospects', 'Rendez-vous confirmé', null, '{"subject": "Rendez-vous confirmé : visite de vos immeubles le 16 octobre", "pre": "Julie N. sera sur place à 10 h.", "label": "Rendez-vous", "icon": "calendar", "eyebrow": "Rendez-vous", "title": "À vendredi, Mathieu", "blocks": [["event", {"mon": "OCT.", "day": "16", "time": "Vendredi 16 octobre · 10 h", "place": "1260, 3e Avenue, Limoilou · Julie N."}], ["bullets", {"items": ["Durée : environ 45 minutes", "Prévoyez l’accès aux espaces communs et à la chaufferie"]}]], "cta": {"l": "Ajouter à mon agenda", "link": "Changer l’heure"}, "sign": {"ini": "JN", "name": "Julie N.", "role": "Gestionnaire · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vous avez pris rendez-vous avec Lease Lane."}, "spec": {"trigger": "Rendez-vous réservé", "send": "Automatique · rappel la veille", "when": "Immédiat", "lcap": "Transactionnel"}}'::jsonb, 'Rendez-vous confirmé : visite de vos immeubles le 16 octobre', 'Julie N. sera sur place à 10 h.', array['prenom', 'date', 'heure', 'adresse', 'gestionnaire']::text[], 'Rendez-vous réservé', 'auto', false, 'transactional', false, false)
